var a=`0843-uttapam`;var t=`world-0843`;var n=`IN`;var r=`south-asia`;var o=8;var d=1187;var s={en:`Uttapam`,ua:`Уттапам`};var l={en:`Uttapam is a India dish made with idli rice, urad dal, red onion, tomato. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Уттапам, страва кухні країни Індія. Основні складники: рис для ідлі, урід дал, червона цибуля, помідор. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var m=[{en:`Soak the listed rice, grains or noodles in clean water for about 480 minutes as appropriate, then drain; grind rice and urad for batter if required by this dish.`,ua:`Замочіть зазначені рис, крупи або локшину у чистій воді приблизно на 480 хвилин залежно від продукту, потім злийте; для тіста за потреби подрібніть рис і урад.`,t:[`rice-soaking`],m:480,i:[[`idli-rice`,310,`g`],[`urad-dal`,110,`g`],[`water`,850,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`water`,230,`ml`],[`table-salt`,6,`g`]]},{en:`Leave the mixed rice-and-legume batter loosely covered in a clean warm place for about 660 minutes until aerated and tangy. Fermentation times vary; avoid overheating.`,ua:`Залиште суміш рисового тіста з бобовими нещільно накритою в чистому теплому місці на приблизно 660 хвилин до бульбашок та легкої кислинки. Час змінюється; не перегрівайте.`,t:[`mixed-grain-fermentation`],m:660,i:[]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`red-onion`,170,`g`],[`tomato`,190,`g`],[`serrano-pepper`,2,`pcs`]]},{en:`Ladle fermented batter onto a hot greased griddle, sprinkle chopped vegetables on top and cook both sides of each thick uttapam.`,ua:`Вилийте ферментоване тісто на гарячу змащену сковороду, посипте нарізаними овочами та обсмажте товсті уттапами з обох боків.`,t:[`griddle-cooking`],m:22,i:[[`canola-oil`,35,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,20,`g`]]}];var g={slug:a,id:t,country:`IN`,region:r,servings:8,minutes:d,title:s,text:l,steps:m};export{n as country,g as default,t as id,d as minutes,r as region,o as servings,a as slug,m as steps,l as text,s as title};